import RNA, random, multiprocessing as mp, time, sys
target = "((......((......))......(((......((......))......((......))......)))......))....."
def worker(seed):
    random.seed(seed)
    best=None; best_d=999
    for _ in range(50):
        start=''.join(random.choice('ACGU') for _ in range(len(target)))
        seq, d = RNA.inverse_fold(start, target)
        if d < best_d:
            best_d=d; best=seq
        if d == 0 and RNA.fold_compound(seq).mfe()[0] == target:
            return (seq, 0)
    return (best, best_d)
if __name__ == '__main__':
    t0=time.time()
    with mp.Pool(64) as p:
        results=[]
        for r in p.imap_unordered(worker, range(512)):
            results.append(r)
            if r[1]==0:
                print('SOLVED', r[0]); p.terminate(); break
        if results and results[-1][1]!=0:
            results.sort()
            print('best', results[0][1], results[0][0])
    print('elapsed', time.time()-t0)
